17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.LocalDate;
23	import java.util.ArrayList;
24	import java.util.Collection;
25	import java.util.Comparator;
26	import java.util.List;
27	import java.util.Locale;
28	import java.util.Map;
29	import java.util.Set;
30	import java.util.regex.Pattern;
31	
32	import org.slf4j.Logger;
33	import org.slf4j.LoggerFactory;
34	import org.springframework.http.HttpHeaders;
35	import org.springframework.http.HttpStatus;
36	import org.springframework.http.ResponseEntity;
37	import org.springframework.samples.petclinic.mapper.OwnerMapper;
38	import org.springframework.samples.petclinic.mapper.PetMapper;
39	import org.springframework.samples.petclinic.mapper.VisitMapper;
40	import org.springframework.samples.petclinic.model.Owner;
41	import org.springframework.samples.petclinic.model.Pet;
42	import org.springframework.samples.petclinic.model.Visit;
43	import org.springframework.samples.petclinic.rest.advice.CityAtCapacityException;
44	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitException;
45	import org.springframework.samples.petclinic.rest.advice.DisposableEmailException;
46	import org.springframework.samples.petclinic.rest.advice.DuplicateIdentityException;
47	import org.springframework.samples.petclinic.rest.advice.FutureRegistrationDateException;
48	import org.springframework.samples.petclinic.rest.advice.HouseholdDuplicateException;
49	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
50	import org.springframework.samples.petclinic.rest.advice.InvalidPostcodeException;
51	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
52	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
53	import org.springframework.samples.petclinic.rest.api.OwnersApi;
54	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
55	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
56	import org.springframework.samples.petclinic.rest.dto.PetDto;
57	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
58	import org.springframework.samples.petclinic.rest.dto.VisitDto;
59	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
60	import org.springframework.samples.petclinic.service.ClinicService;
61	import org.springframework.security.access.prepost.PreAuthorize;
62	import org.springframework.web.bind.annotation.CrossOrigin;
63	import org.springframework.web.bind.annotation.RequestMapping;
64	import org.springframework.web.bind.annotation.RestController;
65	import org.springframework.web.util.UriComponentsBuilder;
66	
67	import jakarta.transaction.Transactional;
68	
69	/**
70	 * @author Vitaliy Fedoriv
71	 */
72	
73	@RestController
74	@CrossOrigin(exposedHeaders = "errors, content-type")
75	@RequestMapping("/api")
76	public class OwnerRestControllerV1 implements OwnersApi {
77	
78	    /**
79	     * Matches a syntactically valid email: a non-empty local part and domain separated by a single
80	     * '@', with at least one dot-separated label in the domain and no whitespace anywhere.
81	     */
82	    private static final Pattern EMAIL_PATTERN =
83	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
84	
85	    /**
86	     * Email domains rejected as disposable/throwaway addresses. An owner whose email domain matches
87	     * one of these (compared case-insensitively) is rejected with 400.
88	     */
89	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
90	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
91	
92	    /**
93	     * Dedicated audit logger. On a successful owner create an audit line is emitted carrying the
94	     * new owner's id, customerCode, registrationDate and membershipLevel.
95	     */
96	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
97	
98	    /**
99	     * Common street-type abbreviations expanded during address normalization, keyed by the
100	     * upper-cased abbreviation.
101	     */
102	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
103	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
104	
105	    /**
106	     * Maximum number of owners a single city may contain. A create is rejected once the owner's
107	     * city already holds this many owners.
108	     */
109	    private static final int CITY_CAPACITY = 50;
110	
111	    /**
112	     * Maximum number of owners that may be created on a single day. A create is rejected once this
113	     * many owners already carry the current day as their {@code registrationDate}.
114	     */
115	    private static final int DAILY_OWNER_LIMIT = 100;
116	
117	    private final ClinicService clinicService;
118	
119	    private final OwnerMapper ownerMapper;
120	
121	    private final PetMapper petMapper;
122	
123	    private final VisitMapper visitMapper;
124	
125	    public OwnerRestControllerV1(ClinicService clinicService,
126	                                 OwnerMapper ownerMapper,
127	                                 PetMapper petMapper,
128	                                 VisitMapper visitMapper) {
129	        this.clinicService = clinicService;
130	        this.ownerMapper = ownerMapper;
131	        this.petMapper = petMapper;
132	        this.visitMapper = visitMapper;
133	    }
134	
135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
138	        Collection<Owner> owners;
139	        if (lastName != null) {
140	            owners = this.clinicService.findOwnerByLastName(lastName);
141	        } else {
142	            owners = this.clinicService.findAllOwners();
143	        }
144	        if (owners.isEmpty()) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Override
152	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
153	        Owner owner = this.clinicService.findOwnerById(ownerId);
154	        if (owner == null) {
155	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
156	        }
157	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Override
162	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
163	        validateRequiredFields(ownerFieldsDto);
164	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
165	        HttpHeaders headers = new HttpHeaders();
166	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
167	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
168	        rejectFutureRegistrationDate(owner.getRegistrationDate());
169	        LocalDate effectiveDate = owner.getRegistrationDate() == null
170	            ? LocalDate.now()
171	            : owner.getRegistrationDate();
172	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
173	        rejectWhenDailyLimitReached(owner.getRegistrationDate());
174	        rejectWhenCityAtCapacity(owner.getCity());
175	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
176	        applyHousehold(owner, sharesHousehold);
177	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
178	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
179	        rejectDuplicateIdentity(owner);
180	        owner.setCustomerCode(customerCode(owner));
181	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
182	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
183	        flagPossibleDuplicate(owner, sharesHousehold);
184	        this.clinicService.saveOwner(owner);
185	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
186	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
187	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
188	            ownerDto.getMembershipLevel());
189	        headers.setLocation(UriComponentsBuilder.newInstance()
190	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
191	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
192	    }
193	
194	    /**
195	     * Builds the owner's customer code, formatted {@code <REGION>-<HASH8>} where REGION is the region
196	     * code derived from the owner's postcode (falling back to the city-to-region table, then
197	     * {@code UNKNOWN}) and HASH8 is the first 8 upper-cased hex characters of the SHA-256 of the
198	     * owner's normalized telephone concatenated with its last name (e.g. {@code NSW-1A2B3C4D}). The
199	     * code is a pure function of the owner's region and identity, carrying no sequence number.
200	     *
201	     * @param owner the owner being created, with its normalized telephone already applied
202	     * @return the assigned customer code
203	     */
204	    private String customerCode(Owner owner) {
205	        return regionCode(owner) + "-" + identityHash8(owner.getTelephone(), owner.getLastName());
206	    }
207	
208	    /**
209	     * Derives the region code embedded in an owner's customer code, preferring the postcode: a
210	     * 4-digit postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099,
211	     * QLD 4000-4099) yields that region. Otherwise the city-to-region table (Sydney->NSW,
212	     * Melbourne->VIC, Brisbane->QLD) is consulted, returning {@code UNKNOWN} when neither the
213	     * postcode nor the city identifies a region.
214	     *
215	     * @param owner the owner being created
216	     * @return the derived region code, never {@code null}
217	     */
218	    private String regionCode(Owner owner) {
219	        String fromPostcode = regionFromPostcode(owner.getPostcode());
220	        if (fromPostcode != null) {
221	            return fromPostcode;
222	        }
223	        String fromCity = region(owner.getCity());
224	        return fromCity == null ? "UNKNOWN" : fromCity;
225	    }
226	
227	    /**
228	     * Resolves the region whose postcode range contains the given postcode, or {@code null} when the
229	     * postcode is absent, not 4 digits, or in no known range.
230	     *
231	     * @param postcode the owner's postcode, may be {@code null}
232	     * @return the region code, or {@code null} when no known range contains the postcode
233	     */
234	    private String regionFromPostcode(String postcode) {
235	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
236	            return null;
237	        }
238	        int value = Integer.parseInt(postcode);
239	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
240	            int[] range = entry.getValue();
241	            if (value >= range[0] && value <= range[1]) {
242	                return entry.getKey();
243	            }
244	        }
245	        return null;
246	    }
247	
248	    /**
249	     * Computes the identity hash embedded in an owner's customer code: the first 8 upper-cased hex
250	     * characters of the SHA-256 of the owner's normalized telephone concatenated with its last name.
251	     *
252	     * @param telephone the owner's normalized (E.164) telephone
253	     * @param lastName  the owner's last name
254	     * @return the 8-character upper-cased hex hash
255	     */
256	    private String identityHash8(String telephone, String lastName) {
257	        String input = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
258	        try {
259	            byte[] digest = MessageDigest.getInstance("SHA-256")
260	                .digest(input.getBytes(StandardCharsets.UTF_8));
261	            StringBuilder hex = new StringBuilder(digest.length * 2);
262	            for (byte b : digest) {
263	                hex.append(String.format("%02x", b));
264	            }
265	            return hex.substring(0, 8).toUpperCase(Locale.ROOT);
266	        } catch (NoSuchAlgorithmException ex) {
267	            throw new IllegalStateException("SHA-256 not available", ex);
268	        }
269	    }
270	
271	    /**
272	     * Builds the owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the
273	     * last two digits of the registrationDate year, zero-padded (e.g. {@code NSW-1A2B3C4D-M26}).
274	     *
275	     * @param customerCode     the owner's assigned customer code
276	     * @param registrationDate the owner's registration date
277	     * @return the assigned membership number
278	     */
279	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
280	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
281	    }
282	
283	    /**
284	     * Counts the existing owners that already share the given firstName and lastName, compared
285	     * case-insensitively. Evaluated before the owner being created is saved, so it reflects only
286	     * the owners that pre-existed this create.
287	     *
288	     * @param firstName the new owner's first name
289	     * @param lastName  the new owner's last name
290	     * @return the number of existing namesakes
291	     */
292	    private int countNamesakes(String firstName, String lastName) {
293	        return (int) this.clinicService.findAllOwners().stream()
294	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
295	                && equalsIgnoreCase(existing.getLastName(), lastName))
296	            .count();
297	    }
298	
299	    /**
300	     * Flags an owner as a possible (soft) duplicate. Although it is not a hard duplicate (its whole
301	     * {@link #identityKey(Owner) identityKey} is unique, so the create was not rejected), it may
302	     * still resemble an existing owner: when it shares an existing owner's lastName (compared
303	     * case-insensitively) and postcode while carrying a different telephone, the owner is flagged
304	     * with {@code possibleDuplicate=true} and {@code possibleDuplicateOf} set to that existing
305	     * owner's id. When no such owner exists the flag is set to {@code false} and no match id is
306	     * recorded. An owner with no postcode can never soft-match and is always {@code false}.
307	     *
308	     * <p>A declared household member (created with {@code sharesHousehold=true}) is never a suspected
309	     * duplicate: its match with an existing household member is a deliberate, declared one, so it is
310	     * always flagged {@code false}.
311	     *
312	     * @param owner           the owner being created, with its normalized telephone already applied
313	     * @param sharesHousehold whether the request declared it shares a household; a declared member is
314	     *                        never flagged as a possible duplicate
315	     */
316	    private void flagPossibleDuplicate(Owner owner, boolean sharesHousehold) {
317	        Owner match = sharesHousehold ? null : findPossibleDuplicate(owner);
318	        if (match != null) {
319	            owner.setPossibleDuplicate(true);
320	            owner.setPossibleDuplicateOf(match.getId());
321	        } else {
322	            owner.setPossibleDuplicate(false);
323	            owner.setPossibleDuplicateOf(null);
324	        }
325	    }
326	
327	    /**
328	     * Finds the existing owner this owner soft-matches: same lastName (case-insensitive) and same
329	     * postcode, but a different telephone. When several existing owners match, the one with the
330	     * lowest id is chosen so the result is deterministic. Returns {@code null} when the owner has no
331	     * postcode or no such existing owner exists.
332	     *
333	     * @param owner the owner being created
334	     * @return the matching existing owner, or {@code null} when there is no soft-match
335	     */
336	    private Owner findPossibleDuplicate(Owner owner) {
337	        if (isBlank(owner.getPostcode())) {
338	            return null;
339	        }
340	        return this.clinicService.findAllOwners().stream()
341	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
342	                && owner.getPostcode().equals(existing.getPostcode())
343	                && !equalsIgnoreCase(existing.getTelephone(), owner.getTelephone()))
344	            .min(Comparator.comparing(Owner::getId))
345	            .orElse(null);
346	    }
347	
348	    /**
349	     * Rejects creating an owner when their city already contains {@link #CITY_CAPACITY} or more
350	     * owners. Existing owners are counted case-insensitively by city, matching how the per-city
351	     * customer-code sequence is derived.
352	     *
353	     * @param city the new owner's city
354	     * @throws CityAtCapacityException if the city already holds {@link #CITY_CAPACITY} owners
355	     */
356	    private void rejectWhenCityAtCapacity(String city) {
357	        long count = this.clinicService.findAllOwners().stream()
358	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
359	            .count();
360	        if (count >= CITY_CAPACITY) {
361	            throw new CityAtCapacityException(city);
362	        }
363	    }
364	
365	    /**
366	     * Rejects creating an owner once {@link #DAILY_OWNER_LIMIT} or more owners already carry the
367	     * given business day as their {@code registrationDate}. The day is the owner's adjusted,
368	     * business-day registration date, so the limit is enforced per business day and weekend
369	     * requests count against the Monday they roll forward to.
370	     *
371	     * @param registrationDate the owner's adjusted (business-day) registration date
372	     * @throws DailyOwnerLimitException if {@link #DAILY_OWNER_LIMIT} owners already carry that
373	     *                                  registration date
374	     */
375	    private void rejectWhenDailyLimitReached(LocalDate registrationDate) {
376	        long count = this.clinicService.findAllOwners().stream()
377	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
378	            .count();
379	        if (count >= DAILY_OWNER_LIMIT) {
380	            throw new DailyOwnerLimitException(registrationDate);
381	        }
382	    }
383	
384	    /**
385	     * Rejects creating an owner whose supplied {@code registrationDate} lies in the future, i.e. is
386	     * later than the current server date. A {@code null} registration date is accepted (it defaults
387	     * to the server date) and today or any past date is allowed; only a future value is rejected.
388	     *
389	     * @param registrationDate the registration date supplied on the request, may be {@code null}
390	     * @throws FutureRegistrationDateException if the supplied date is later than the server date
391	     */
392	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
393	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
394	            throw new FutureRegistrationDateException(registrationDate);
395	        }
396	    }
397	
398	    /**
399	     * Rolls a registration date forward onto a business day: when it falls on a Saturday or Sunday
400	     * it advances to the following Monday, otherwise it is returned unchanged. Applied to the
401	     * effective registration date (whether supplied in the request or defaulted to the server date)
402	     * so a weekend value never persists as an owner's {@code registrationDate}.
403	     *
404	     * @param date the effective registration date
405	     * @return the same date when it is a weekday, otherwise the next Monday
406	     */
407	    private LocalDate toBusinessDay(LocalDate date) {
408	        return switch (date.getDayOfWeek()) {
409	            case SATURDAY -> date.plusDays(2);
410	            case SUNDAY -> date.plusDays(1);
411	            default -> date;
412	        };
413	    }
414	
415	    private boolean equalsIgnoreCase(String a, String b) {
416	        return a == null ? b == null : a.equalsIgnoreCase(b);
417	    }
418	
419	    /**
420	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
421	     * offending field so the client learns about all of them at once.
422	     *
423	     * @param ownerFieldsDto the submitted owner fields
424	     * @throws MissingOwnerFieldsException if firstName, lastName, address, city or telephone is
425	     *                                     missing or blank
426	     */
427	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
428	        List<String> errors = new ArrayList<>();
429	        if (isBlank(ownerFieldsDto.getFirstName())) {
430	            errors.add("firstName");
431	        }
432	        if (isBlank(ownerFieldsDto.getLastName())) {
433	            errors.add("lastName");
434	        }
435	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
436	            errors.add("address");
437	        }
438	        if (isBlank(ownerFieldsDto.getCity())) {
439	            errors.add("city");
440	        }
441	        if (isBlank(ownerFieldsDto.getTelephone())) {
442	            errors.add("telephone");
443	        }
444	        if (!errors.isEmpty()) {
445	            throw new MissingOwnerFieldsException(errors);
446	        }
447	    }
448	
449	    private boolean isBlank(String value) {
450	        return value == null || value.isBlank();
451	    }
452	
453	    /**
454	     * The fixed inclusive 4-digit postcode range allowed for each region, keyed by region code
455	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
456	     */
457	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
458	        "NSW", new int[] {2000, 2099},
459	        "VIC", new int[] {3000, 3099},
460	        "QLD", new int[] {4000, 4099});
461	
462	    /**
463	     * Validates an owner's postcode, but only when one is supplied. A {@code null} or blank postcode
464	     * is optional and accepted, keeping the create contract backward-compatible. When present the
465	     * value must be 4 digits and, when the owner's city has a known region (Sydney->NSW,
466	     * Melbourne->VIC, Brisbane->QLD), must fall within that region's inclusive range (NSW 2000-2099,
467	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
468	     *
469	     * @param postcode the raw postcode value as submitted, may be {@code null}
470	     * @param city     the owner's city, used to resolve the region whose range applies
471	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for
472	     *                                  the city's region
473	     */
474	    private void validatePostcode(String postcode, String city) {
475	        if (isBlank(postcode)) {
476	            return;
477	        }
478	        if (!postcode.matches("[0-9]{4}")) {
479	            throw new InvalidPostcodeException(postcode, city);
480	        }
481	        String region = region(city);
482	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
483	        if (range != null) {
484	            int value = Integer.parseInt(postcode);
485	            if (value < range[0] || value > range[1]) {
486	                throw new InvalidPostcodeException(postcode, city);
487	            }
488	        }
489	    }
490	
491	    /**
492	     * Derives an owner's region from its city using the fixed city-to-region table (Sydney->NSW,
493	     * Melbourne->VIC, Brisbane->QLD), returning {@code null} when the city is not in the table.
494	     *
495	     * @param city the owner's city
496	     * @return the region code, or {@code null} when the city has no known region
497	     */
498	    private String region(String city) {
499	        if (city == null) {
500	            return null;
501	        }
502	        return switch (city) {
503	            case "Sydney" -> "NSW";
504	            case "Melbourne" -> "VIC";
505	            case "Brisbane" -> "QLD";
506	            default -> null;
507	        };
508	    }
509	
510	    /**
511	     * The number of national (subscriber) digits an E.164 number must carry for a given country
512	     * calling code, keyed by that code (without the leading '+'). Australia ('+61') requires 9
513	     * national digits and the North American Numbering Plan ('+1') requires 10.
514	     */
515	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
516	        Map.of("61", 9, "1", 10);
517	
518	    /**
519	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
520	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
521	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
522	     * followed by 8 to 15 digits, and its national-number length must match the one required by its
523	     * country calling code ('+61' requires 9 national digits, '+1' requires 10).
524	     *
525	     * @param telephone the raw telephone value as submitted
526	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
527	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
528	     *                                   national-number length is wrong for its country code
529	     */
530	    private String normalizeTelephone(String telephone) {
531	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
532	        String nationalSignificantNumber;
533	        if (cleaned.startsWith("+")) {
534	            nationalSignificantNumber = cleaned.substring(1);
535	        } else {
536	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
537	            nationalSignificantNumber = "61" + national;
538	        }
539	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
540	            throw new InvalidTelephoneException(telephone);
541	        }
542	        validateNationalNumberLength(nationalSignificantNumber, telephone);
543	        return "+" + nationalSignificantNumber;
544	    }
545	
546	    /**
547	     * Validates the national-number length of an E.164 number against its country calling code. The
548	     * significant number is a country code immediately followed by the national digits; for each
549	     * known code in {@link #NATIONAL_NUMBER_LENGTHS} the remaining national digits must number
550	     * exactly the required amount ('+61' requires 9, '+1' requires 10). Codes with no known rule are
551	     * left unchecked.
552	     *
553	     * @param nationalSignificantNumber the E.164 digits following the '+' (country code + national)
554	     * @param rejectedValue             the raw telephone value, reported on rejection
555	     * @throws InvalidTelephoneException if the national-number length is wrong for the country code
556	     */
557	    private void validateNationalNumberLength(String nationalSignificantNumber, String rejectedValue) {
558	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
559	            String countryCode = rule.getKey();
560	            if (nationalSignificantNumber.startsWith(countryCode)) {
561	                int nationalDigits = nationalSignificantNumber.length() - countryCode.length();
562	                if (nationalDigits != rule.getValue()) {
563	                    throw new InvalidTelephoneException(rejectedValue);
564	                }
565	                return;
566	            }
567	        }
568	    }
569	
570	    /**
571	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
572	     * value is treated as absent and returns {@code null}); when present the value must be a
573	     * syntactically valid address, and is stored and returned lower-cased.
574	     *
575	     * @param email the raw email value as submitted, may be {@code null}
576	     * @return the lower-cased email, or {@code null} when none was supplied
577	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
578	     */
579	    private String normalizeEmail(String email) {
580	        if (email == null || email.isBlank()) {
581	            return null;
582	        }
583	        String normalized = email.trim().toLowerCase();
584	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
585	            throw new InvalidEmailException(email);
586	        }
587	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
588	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
589	            throw new DisposableEmailException(email);
590	        }
591	        return normalized;
592	    }
593	
594	    /**
595	     * The single, consolidated duplicate check. Rejects the owner being created when its whole
596	     * {@link #identityKey(Owner) identityKey} exactly equals that of an existing owner. Because the
597	     * key is the normalized telephone, email and householdId joined together, this one check
598	     * subsumes the former separate telephone, email and household duplicate rules: only an exact
599	     * full-key match counts as a duplicate, so two members of the same household (same householdId)
600	     * with different telephones have different keys and are both allowed.
601	     *
602	     * @param owner the owner being created, with its normalized telephone, email and householdId
603	     *              already applied
604	     * @throws DuplicateIdentityException if another owner already has the same identityKey
605	     */
606	    private void rejectDuplicateIdentity(Owner owner) {
607	        String identityKey = identityKey(owner);
608	        boolean inUse = this.clinicService.findAllOwners().stream()
609	            .map(this::identityKey)
610	            .anyMatch(identityKey::equals);
611	        if (inUse) {
612	            throw new DuplicateIdentityException(identityKey);
613	        }
614	    }
615	
616	    /**
617	     * Derives an owner's {@code identityKey}: {@code normalizedTelephone + '|' + (email or empty) +
618	     * '|' + householdId}. A {@code null} email or householdId contributes an empty segment. Every
619	     * duplicate decision is made by comparing whole identityKeys.
620	     *
621	     * @param owner the owner whose identityKey to derive
622	     * @return the derived identityKey
623	     */
624	    private String identityKey(Owner owner) {
625	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
626	        String email = owner.getEmail() == null ? "" : owner.getEmail();
627	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
628	        return telephone + "|" + email + "|" + householdId;
629	    }
630	
631	    /**
632	     * Applies the household rule to an owner being created. The household is keyed on
633	     * (lastName, postcode): the owner is assigned the deterministic {@link #householdId(Owner)
634	     * householdId} derived from its normalized lastName and postcode, so owners sharing a lastName
635	     * and postcode automatically share the identifier — the link is computed, not created by a flag.
636	     *
637	     * <p>Because the household is keyed on (lastName, postcode), any existing owner that derives the
638	     * same householdId is a member of the same household, and a second owner joining it is a
639	     * household duplicate. Such a create is rejected with 409 unless the request declares
640	     * {@code sharesHousehold=true}, in which case it is allowed through as a declared household
641	     * member. The {@code sharesHousehold} directive only bypasses this duplicate block.
642	     *
643	     * @param owner           the owner being created
644	     * @param sharesHousehold whether the request declared it shares a household, bypassing the block
645	     * @throws HouseholdDuplicateException if an existing owner already shares the household and the
646	     *                                     request did not declare {@code sharesHousehold=true}
647	     */
648	    private void applyHousehold(Owner owner, boolean sharesHousehold) {
649	        String householdId = householdId(owner);
650	        owner.setHouseholdId(householdId);
651	        boolean householdExists = this.clinicService.findAllOwners().stream()
652	            .anyMatch(existing -> householdId.equals(householdId(existing)));
653	        if (householdExists && !sharesHousehold) {
654	            throw new HouseholdDuplicateException(householdId);
655	        }
656	    }
657	
658	    /**
659	     * Derives the stable, shared household identifier for an owner, formatted {@code HH-<HEX12>}
660	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the owner's normalized
661	     * lastName, a {@code '|'} separator, and its postcode. Being a pure function of (lastName,
662	     * postcode), every owner sharing a lastName and postcode derives the same value regardless of
663	     * creation order. A {@code null} postcode contributes an empty segment.
664	     *
665	     * @param owner the owner whose household identifier to derive
666	     * @return the household identifier
667	     */
668	    private String householdId(Owner owner) {
669	        String lastNameKey = toHouseholdKey(owner.getLastName());
670	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
671	        try {
672	            byte[] digest = MessageDigest.getInstance("SHA-256")
673	                .digest((lastNameKey + "|" + postcode).getBytes(StandardCharsets.UTF_8));
674	            StringBuilder hex = new StringBuilder(digest.length * 2);
675	            for (byte b : digest) {
676	                hex.append(String.format("%02x", b));
677	            }
678	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
679	        } catch (NoSuchAlgorithmException ex) {
680	            throw new IllegalStateException("SHA-256 not available", ex);
681	        }
682	    }
683	
684	    /**
685	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
686	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
687	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
688	     * string.
689	     */
690	    private String toHouseholdKey(String value) {
691	        if (value == null) {
692	            return "";
693	        }
694	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
695	    }
696	
697	    /**
698	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
699	     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
700	     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
701	     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
702	     * value, or one that is blank once trimmed, normalizes to an empty string.
703	     *
704	     * @param address the raw address value as submitted, may be {@code null}
705	     * @return the normalized address, or an empty string when none was supplied
706	     */
707	    private String normalizeAddress(String address) {
708	        if (address == null) {
709	            return "";
710	        }
711	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
712	        if (collapsed.isEmpty()) {
713	            return "";
714	        }
715	        String[] tokens = collapsed.split(" ");
716	        StringBuilder normalized = new StringBuilder(collapsed.length());
717	        for (int i = 0; i < tokens.length; i++) {
718	            if (i > 0) {
719	                normalized.append(' ');
720	            }
721	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
722	        }
723	        return normalized.toString();
724	    }
725	
726	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
727	    @Override
728	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
729	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
730	        if (currentOwner == null) {
731	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
732	        }
733	        currentOwner.setAddress(ownerFieldsDto.getAddress());
734	        currentOwner.setCity(ownerFieldsDto.getCity());
735	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
736	        currentOwner.setLastName(ownerFieldsDto.getLastName());
737	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
738	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
739	        this.clinicService.saveOwner(currentOwner);
740	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
741	    }
742	
743	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
744	    @Transactional
745	    @Override
746	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
747	        Owner owner = this.clinicService.findOwnerById(ownerId);
748	        if (owner == null) {
749	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
750	        }
751	        this.clinicService.deleteOwner(owner);
752	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
753	    }
754	
755	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
756	    @Override
757	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
758	        Owner owner = this.clinicService.findOwnerById(ownerId);
759	        if (owner == null) {
760	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
761	        }
762	        HttpHeaders headers = new HttpHeaders();
763	        Pet pet = petMapper.toPet(petFieldsDto);
764	        owner.setId(ownerId);
765	        pet.setOwner(owner);
766	        pet.getType().setName(null);
767	        this.clinicService.savePet(pet);
768	        PetDto petDto = petMapper.toPetDto(pet);
769	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
770	            .buildAndExpand(pet.getId()).toUri());
771	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
772	    }
773	
774	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
775	    @Override
776	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
777	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
778	        if (currentOwner != null) {
779	            Pet currentPet = this.clinicService.findPetById(petId);
780	            if (currentPet != null) {
781	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
782	                currentPet.setName(petFieldsDto.getName());
783	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
784	                this.clinicService.savePet(currentPet);
785	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
786	            }
787	        }
788	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
789	    }
790	
791	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
792	    @Override
793	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
794	        HttpHeaders headers = new HttpHeaders();
795	        Visit visit = visitMapper.toVisit(visitFieldsDto);
796	        Pet pet = new Pet();
797	        pet.setId(petId);
798	        visit.setPet(pet);
799	        this.clinicService.saveVisit(visit);
800	        VisitDto visitDto = visitMapper.toVisitDto(visit);
801	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
802	            .buildAndExpand(visit.getId()).toUri());
803	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
804	    }
805	
806	
807	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
808	    @Override
809	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
810	        Owner owner = this.clinicService.findOwnerById(ownerId);
811	        if (owner != null) {
812	            Pet pet = owner.getPet(petId);
813	            if (pet != null) {
814	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
815	            }
816	        }
817	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
818	    }
819	}
